#!/usr/bin/env python3
"""Summarize recorded gateway token usage; never turn missing prices into a bill."""
import argparse,json,pathlib
p=argparse.ArgumentParser();p.add_argument('--aggregate',required=True);p.add_argument('--preflight',required=True);p.add_argument('--reviewer-preflight',required=True);p.add_argument('--out',required=True);a=p.parse_args();out=pathlib.Path(a.out)
if out.exists():raise SystemExit('refusing overwrite')
x=json.loads(pathlib.Path(a.aggregate).read_text());pre=json.loads(pathlib.Path(a.preflight).read_text());smoke=json.loads(pathlib.Path(a.reviewer_preflight).read_text());arms=x['arms'];cats={}
for name,rows,calls in [('taskRuns',[z['gatewayUsage'] for z in arms.values()],sum(z['modelCalls'] for z in arms.values())),('blindMachineReviews',list(x['reviews']['usageByModel'].values()),sum(z['calls'] for z in x['reviews']['usageByModel'].values())),('postHocAutonomyAudits',list(x['postHocAutonomyMachineAudit']['usageByModel'].values()),sum(z['calls'] for z in x['postHocAutonomyMachineAudit']['usageByModel'].values()))]:
 cats[name]={'calls':calls,'promptTokensReported':sum(z.get('promptTokens',0) for z in rows),'completionTokensReported':sum(z.get('completionTokens',0) for z in rows),'cachedPromptTokensReported':sum(z.get('cachedPromptTokens',0) for z in rows),'callsWithoutUsage':sum(z.get('callsWithoutUsage',0) for z in rows),'requestBytesRecorded':sum(z.get('requestBytes',0) for z in rows),'responseBytesRecorded':sum(z.get('responseBytes',0) for z in rows)}
cats['syntheticPreflight']={'calls':pre['lookupProbe']['modelCalls']+pre['memoryToolProbe']['modelCalls']+smoke['modelCalls'],'promptTokensReported':pre['lookupProbe']['promptTokens']+pre['memoryToolProbe']['promptTokens']+smoke['promptTokens'],'completionTokensReported':pre['lookupProbe']['completionTokens']+pre['memoryToolProbe']['completionTokens']+smoke['completionTokens'],'cachedPromptTokensReported':None,'callsWithoutUsage':0,'requestBytesRecorded':None,'responseBytesRecorded':None,'note':'One reviewer smoke did not report cache details; request/response bytes were not retained for all initial setup calls.'}
result={'categories':cats,'totals':{'calls':sum(z['calls'] for z in cats.values()),'promptTokensReported':sum(z['promptTokensReported'] for z in cats.values()),'completionTokensReported':sum(z['completionTokensReported'] for z in cats.values()),'knownCachedPromptTokens':sum(z['cachedPromptTokensReported'] or 0 for z in cats.values()),'cachedPromptTokensComplete':False},'actualInvoice':'UNKNOWN','actualPerAttempt':'UNKNOWN','actualPerVerifiedSuccess':'UNKNOWN','unpriced':['provider routes and discounts','uncaptured historical ingestion and compaction','local compute and storage','network and service overhead','human labor','engineering and evaluation work'], 'notes':['Cached tokens can be included in prompt totals; do not add them twice.','Request/response byte counts omit headers, TLS and transport overhead.','Provider-reported token counts are not reconciled invoices.','Evaluation and synthetic setup usage are separated from task runs.']};out.parent.mkdir(parents=True,exist_ok=True);out.write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result['totals']))
